 static Window Dialog(string title,double height){var w=new Window{Owner=Application.Current.MainWindow,Title=title,Width=620,Height=height,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=new SolidColorBrush(Color.FromRgb(30,32,36)),Foreground=Brushes.Gainsboro,ShowInTaskbar=false};w.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape){e.Handled=true;w.Close();}};return w;}
