 void Start(){var image=host.CurrentImage;if(image==null)return;bool lockscreen=false;var choice=Dialog("Use image as…",180);var row=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};row.Children.Add(Button("Set as wallpaper",()=>choice.DialogResult=true));row.Children.Add(Button("Set as lockscreen",()=>{lockscreen=true;choice.DialogResult=true;}));row.Children.Add(Button("Cancel",choice.Close));choice.Content=row;if(choice.ShowDialog()!=true)return;
  var window=Dialog(lockscreen?"Lockscreen preview":"Wallpaper preview",630);var panel=new StackPanel{Margin=new Thickness(18)};panel.Children.Add(new TextBlock{Text="Screen / aspect ratio",Margin=new Thickness(5)});var screens=System.Windows.Forms.Screen.AllScreens;var screenNames=screens.Select(s=>$"{s.DeviceName} — {s.Bounds.Width} × {s.Bounds.Height}").ToArray();var choices=screenNames.Concat(new[]{"16:9","16:10","4:3","21:9","32:9","9:16"}).ToArray();var ratio=new ComboBox{ItemsSource=choices,SelectedIndex=0,Margin=new Thickness(5)};panel.Children.Add(ratio);
  var layout=new ComboBox{ItemsSource=new[]{"Fill","Fit","Stretch","Center","Tile","Span"},SelectedIndex=0,Margin=new Thickness(5)};panel.Children.Add(layout);var preview=new Image{Width=540,Height=304,Stretch=Stretch.Uniform,Cursor=Cursors.SizeAll};panel.Children.Add(preview);panel.Children.Add(new TextBlock{Text="Drag the preview to adjust framing. Saved images match the selected screen's resolution; custom ratios use a 1920px width.",TextWrapping=TextWrapping.Wrap,FontSize=11,Margin=new Thickness(5)});
  double zoom=1;Vector framing=new();Point down=default;Vector before=default;bool dragging=false;int width=1920,height=1080;
  void Dimensions(){if(ratio.SelectedIndex<screens.Length){var bounds=screens[ratio.SelectedIndex].Bounds;width=bounds.Width;height=bounds.Height;}else{var parts=((string)ratio.SelectedItem).Split(':');width=1920;height=(int)Math.Round(width*double.Parse(parts[1])/double.Parse(parts[0]));}if((string)layout.SelectedItem=="Span"){width=System.Windows.Forms.SystemInformation.VirtualScreen.Width;height=System.Windows.Forms.SystemInformation.VirtualScreen.Height;}}
