   else{using var key=Registry.CurrentUser.OpenSubKey(@"Control Panel\Desktop",true)??throw new IOException("Windows desktop settings are unavailable.");key.SetValue("WallpaperStyle",mode=="Span"?"22":"2");key.SetValue("TileWallpaper","0");if(!SystemParametersInfo(20,0,file,3))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());host.Toast("Wallpaper updated");}window.Close();}catch(Exception ex){host.Toast(ex.Message);}finally{apply.IsEnabled=true;}};buttons.Children.Add(apply);buttons.Children.Add(Button("Cancel",window.Close));panel.Children.Add(buttons);window.Content=panel;Render();window.ShowDialog();
