 public static BitmapSource Frame(BitmapSource image,int width,int height,string mode,Vector offset,int screenWidth,double zoom=1){var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){var bounds=new Rect(0,0,width,height);dc.DrawRectangle(Brushes.Black,null,bounds);dc.PushClip(new RectangleGeometry(bounds));double sx=width/(double)image.PixelWidth,sy=height/(double)image.PixelHeight;double scale=mode=="Fit"?Math.Min(sx,sy):mode is "Center" or "Tile"?width/(double)screenWidth:Math.Max(sx,sy);scale*=zoom;double w=mode=="Stretch"?width:image.PixelWidth*scale,h=mode=="Stretch"?height:image.PixelHeight*scale;double x=(width-w)/2+offset.X*width,y=(height-h)/2+offset.Y*height;if(mode is "Fill" or "Span"){x=Math.Clamp(x,width-w,0);y=Math.Clamp(y,height-h,0);}else if(mode=="Fit"){x=Math.Clamp(x,Math.Min(0,width-w),Math.Max(0,width-w));y=Math.Clamp(y,Math.Min(0,height-h),Math.Max(0,height-h));}if(mode=="Tile"){var brush=new ImageBrush(image){TileMode=TileMode.Tile,ViewportUnits=BrushMappingMode.Absolute,Viewport=new Rect(x,y,w,h),Stretch=Stretch.Fill};dc.DrawRectangle(brush,null,bounds);}else dc.DrawImage(image,new Rect(x,y,w,h));dc.Pop();}var result=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);result.Render(visual);result.Freeze();return result;}
 public static string LockscreenScript(string file)=>@"
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Runtime.WindowsRuntime
[Windows.Storage.StorageFile, Windows.Storage, ContentType=WindowsRuntime] | Out-Null
[Windows.System.UserProfile.UserProfilePersonalizationSettings, Windows.System.UserProfile, ContentType=WindowsRuntime] | Out-Null
function Await($operation, $type) {
 $method = [System.WindowsRuntimeSystemExtensions].GetMethods() | Where-Object { $_.Name -eq 'AsTask' -and $_.IsGenericMethod -and $_.GetParameters().Count -eq 1 -and $_.GetParameters()[0].ParameterType.Name -eq 'IAsyncOperation`1' } | Select-Object -First 1
 $task = $method.MakeGenericMethod($type).Invoke($null, @($operation))
 $task.GetAwaiter().GetResult()
}
try {
 if (-not [Windows.System.UserProfile.UserProfilePersonalizationSettings]::IsSupported()) { exit 2 }
 $file = Await ([Windows.Storage.StorageFile]::GetFileFromPathAsync('"+file.Replace("'","''")+@"')) ([Windows.Storage.StorageFile])
 $ok = Await ([Windows.System.UserProfile.UserProfilePersonalizationSettings]::Current.TrySetLockScreenImageAsync($file)) ([bool])
 if ($ok) { exit 0 } else { exit 2 }
} catch { exit 2 }
";
 static async Task<bool> SetLockscreen(string file,string dir){string script=Path.Combine(dir,"set-lockscreen.ps1");await File.WriteAllTextAsync(script,LockscreenScript(file),new System.Text.UTF8Encoding(true));var psi=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe")){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};foreach(string arg in new[]{"-NoProfile","-NonInteractive","-ExecutionPolicy","Bypass","-File",script})psi.ArgumentList.Add(arg);using var process=Process.Start(psi)!;try{using var timeout=new System.Threading.CancellationTokenSource(TimeSpan.FromSeconds(30));await process.WaitForExitAsync(timeout.Token);return process.ExitCode==0;}catch{try{process.Kill(true);}catch{}return false;}finally{try{File.Delete(script);}catch{}}}
